def match(orders):
    trades = []
    buy_book = []  # (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    order_map = {}  # id -> (side, remaining_qty, arrival_time, original_order_type)
    arrival_time = 0

    def add_to_book(side, price, id, qty, arrival_time, order_type):
        if side == 'buy':
            buy_book.append([price, arrival_time, id, qty])
            buy_book.sort(key=lambda x: (-x[0], x[1]))
        else:
            sell_book.append([price, arrival_time, id, qty])
            sell_book.sort(key=lambda x: (x[0], x[1]))

    def process_order(order_type, id, side, price, qty):
        nonlocal arrival_time, trades
        arrival_time += 1
        current_arrival = arrival_time

        remaining_qty = qty

        if side == 'buy':
            # Match against sell_book
            while remaining_qty > 0 and sell_book:
                sell_entry = sell_book[0]
                sell_price, sell_arrival, sell_id, sell_qty = sell_entry

                if sell_price <= price:
                    # Match
                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([id, sell_id, sell_price, trade_qty])
                    remaining_qty -= trade_qty
                    sell_entry[3] -= trade_qty

                    if sell_entry[3] == 0:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                    else:
                        order_map[sell_id] = (order_map[sell_id][0], sell_entry[3], order_map[sell_id][2], order_map[sell_id][3])
                else:
                    break
        else:
            # side == 'sell', match against buy_book
            while remaining_qty > 0 and buy_book:
                buy_entry = buy_book[0]
                buy_price, buy_arrival, buy_id, buy_qty = buy_entry

                if buy_price >= price:
                    # Match
                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, id, buy_price, trade_qty])
                    remaining_qty -= trade_qty
                    buy_entry[3] -= trade_qty

                    if buy_entry[3] == 0:
                        buy_book.pop(0)
                        if buy_id in order_map:
                            del order_map[buy_id]
                    else:
                        order_map[buy_id] = (order_map[buy_id][0], buy_entry[3], order_map[buy_id][2], order_map[buy_id][3])
                else:
                    break

        # Add remaining to book if limit order
        if order_type == 'limit' and remaining_qty > 0:
            add_to_book(side, price, id, remaining_qty, current_arrival, order_type)
            order_map[id] = (side, remaining_qty, current_arrival, order_type)

    for order in orders:
        if order[0] == 'limit':
            _, id, side, price, qty = order
            process_order('limit', id, side, price, qty)
        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            process_order('ioc', id, side, price, qty)
        elif order[0] == 'market':
            _, id, side, qty = order
            process_order('market', id, side, None, qty)
        elif order[0] == 'cancel':
            _, id = order
            if id in order_map:
                side, qty, arr_time, order_type = order_map[id]
                if side == 'buy':
                    buy_book[:] = [e for e in buy_book if e[2] != id]
                else:
                    sell_book[:] = [e for e in sell_book if e[2] != id]
                del order_map[id]

    return trades

